-- ----------------------------
-- Procedure structure for InsertChineseUsers
-- ----------------------------
DROP PROCEDURE IF EXISTS `InsertChineseUsers`;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `InsertChineseUsers`()
BEGIN
    DECLARE i INT DEFAULT 1;
    WHILE i <= 30 DO
            VALUES (
                       /* 生成中文用户名：姓氏+随机双字名 */
                       CONCAT(
                               ELT(FLOOR(1 + RAND()*10), '王','李','张','刘','陈','杨','赵','黄','周','吴'),
                               ELT(FLOOR(1 + RAND()*15), '强','芳','伟','敏','磊','娜','俊','丽','军','辉','婷','杰','斌','宁','浩')
                           ),
                       /* 生成密码哈希：MD5(基础密码+序号) */
                       MD5(CONCAT('mima_', i)),
                       /* 生成规范邮箱：拼音首字母+序号@域名 */
                       CONCAT(
                               ELT(FLOOR(1 + RAND()*10), 'wang','li','zhang','liu','chen','yang','zhao','huang','zhou','wu'),
                               i,
                               '@example.com'
                           ),
                       /* 生成创建时间：过去365天内随机时刻 */
                       DATE_ADD(NOW(), INTERVAL -FLOOR(RAND()*365) DAY)
                   );
            SET i = i + 1;
        END WHILE;
END
;;
DELIMITER ;
