INSERT INTO `cinema` VALUES ('1', '万达影城', '北京朝阳店', '北京市', '朝阳区建国路93号万达广场6层', '010-85671111', '[{\"description\": \"未取票用户放映前30分钟可改签\", \"service_name\": \"改签\"}, {\"description\": \"免费提供抗菌3D眼镜（含儿童款），需支付20元押金\", \"service_name\": \"3D眼镜服务\"}, {\"description\": \"1.2米以下儿童2D普通厅免费观影，IMAX/CINITY厅需购票，每位成人限带1名\", \"service_name\": \"儿童优惠\"}, {\"description\": \"万达广场停车场，首小时免费，后续5元/小时，每日封顶60元\", \"service_name\": \"停车信息\"}]','');
INSERT INTO `cinema` VALUES ('2', 'CGV影城', '上海浦东店', '上海市', '浦东新区世纪大道8号国金中心B2', '021-58352000', '[{\"description\": \"开场前1小时可免费改签，特殊场次除外\", \"service_name\": \"改签规则\"}, {\"description\": \"4DX影厅提供震动同步特效座椅（含一次性坐垫）\", \"service_name\": \"4D设备\"}, {\"description\": \"全日制学生凭有效证件享正价票7折优惠\", \"service_name\": \"学生优惠\"}, {\"description\": \"国金中心停车场，消费满150元免2小时停车费\", \"service_name\": \"停车服务\"}]','');
INSERT INTO `cinema` VALUES ('3', 'UME国际影城', '广州天河店', '广州市', '天河区天河路208号天河城4楼', '020-85591288', '[{\"description\": \"VIP会员可开场前10分钟改签\", \"service_name\": \"改签政策\"}, {\"description\": \"夹片式3D眼镜10元/副（可重复使用）\", \"service_name\": \"眼镜租赁\"}, {\"description\": \"购买家庭套票赠送爆米花套餐\", \"service_name\": \"亲子套餐\"}, {\"description\": \"天河城停车场周末10元/小时，建议地铁至体育西路站\", \"service_name\": \"停车指南\"}]','');
INSERT INTO `cinema` VALUES ('4', '金逸影城', '深圳福田店', '深圳市', '福田区福华三路COCO Park3楼', '0755-82528888', '[{\"description\": \"黄金时段影片不可改签\", \"service_name\": \"改签限制\"}, {\"description\": \"3D眼镜需支付50元押金（可退）\", \"service_name\": \"设备押金\"}, {\"description\": \"钻石会员带2名儿童免费观影\", \"service_name\": \"会员福利\"}, {\"description\": \"COCO Park停车场夜间10元/小时，凭影票减免2小时\", \"service_name\": \"停车收费\"}]','');
INSERT INTO `cinema` VALUES ('5', '博纳影城', '成都锦江店', '成都市', '锦江区红星路三段1号国际金融中心', '028-62092222', '[{\"description\": \"IMAX厅改签需补差价\", \"service_name\": \"特殊改签\"}, {\"description\": \"提供800度以下近视专用3D眼镜\", \"service_name\": \"近视友好\"}, {\"description\": \"60岁以上老人早场票5折（需身份证）\", \"service_name\": \"长者优惠\"}, {\"description\": \"IFS停车场消费满100元免2小时停车费\", \"service_name\": \"停车优惠\"}]','');
INSERT INTO `cinema` VALUES ('6', 'SFC上影影城', '武汉光谷店', '武汉市', '洪山区珞喻路766号光谷世界城', '027-87665555', '[{\"description\": \"会员积分可抵扣改签手续费\", \"service_name\": \"改签规则\"}, {\"description\": \"每场次结束后紫外线消毒3D眼镜\", \"service_name\": \"消毒设备\"}, {\"description\": \"1.1米以下儿童所有影厅均需购票\", \"service_name\": \"儿童政策\"}, {\"description\": \"光谷世界城停车场，首小时3元，每增加半小时2元\", \"service_name\": \"停车说明\"}]','');
INSERT INTO `cinema` VALUES ('7', '万象影城', '杭州萧山店', '杭州市', '萧山区市心北路万象汇4层', '0571-83881234', '[{\"description\": \"开场后30分钟内可改签次日场次\", \"service_name\": \"改签服务\"}, {\"description\": \"双人3D眼镜套装押金30元\", \"service_name\": \"情侣套镜\"}, {\"description\": \"周四学生日享特惠票价\", \"service_name\": \"学生特权\"}, {\"description\": \"万象汇停车场，积分可兑换停车时长\", \"service_name\": \"停车收费\"}]','');
INSERT INTO `cinema` VALUES ('8', '万达影城', '重庆江北店', '重庆市', '江北区北城天街8号', '023-67891234', '[{\"description\": \"IMAX影片改签需支付10%手续费\", \"service_name\": \"改签政策\"}, {\"description\": \"提供4K高清3D眼镜（押金30元）\", \"service_name\": \"设备升级\"}, {\"description\": \"配备母婴室与婴儿推车停放区\", \"service_name\": \"婴儿关怀\"}, {\"description\": \"北城天街停车场，夜间（22:00-8:00）3元/小时\", \"service_name\": \"停车信息\"}]','');
