INSERT INTO `trailer` VALUES ('1', 'https://p0.pipi.cn/mediaplus/friday_image_fe/cdf05c14f876e33de28014c92fdd165dbef3d.jpg?imageView2/1/w/120/h/68', 'https://vod.pipi.cn/fec9203cvodtransbj1251246104/217d34761397757900741755857/v.f42905.mp4', '电影《小小的我》官宣定档，12月31日陪伴大家共迎2025。', '5613000', '1');
INSERT INTO `trailer` VALUES ('2', 'https://p0.pipi.cn/mediaplus/friday_image_fe/cdf05c143e777e3d690511d5ed155c83caba7.jpg?imageView2/1/w/120/h/68', 'https://vod.pipi.cn/fec9203cvodtransbj1251246104/a398c0841397757901230662605/v.f42905.mp4', '电影《小小的我》发布制作特辑，这些小细节你发现了吗？', '991000', '1');
INSERT INTO `trailer` VALUES ('3', 'https://p0.pipi.cn/mediaplus/friday_image_fe/cdf05c147f06e305115be79d4f174a50c4260.jpg?imageView2/1/w/120/h/68', 'https://vod.pipi.cn/fec9203cvodtransbj1251246104/1c869edb1397757900989486523/v.f42905.mp4', '电影《小小的我》特别纪录片发布。', '1005000', '1');
INSERT INTO `trailer` VALUES ('4', 'https://p0.pipi.cn/mediaplus/friday_image_fe/cdf05c149a16e377e15b28a568d931ae504de.jpg?imageView2/1/w/138/h/78', 'https://vod.pipi.cn/fec9203cvodtransbj1251246104/5b0c0e401397757899648031965/v.f42905.mp4', '电影《小小的我》官宣提档，并向观众发起“干杯”邀约！', '25654', '1');
